(() => {
  let numero = ($json.number || '')
    .replace('@s.whatsapp.net', '')
    .replace(/\D/g, '');

  // adiciona 55 se não existir
  if (!numero.startsWith('55')) {
    numero = '55' + numero;
  }

  // se tiver 12 dígitos (faltando o 9)
  if (numero.length === 12) {
    numero = numero.slice(0, 4) + '9' + numero.slice(4);
  }

  // valida tamanho final
  if (numero.length !== 13) {
    return null;
  }

  // valida se é celular (primeiro dígito após DDD deve ser 9)
  if (numero.slice(4, 5) !== '9') {
    return null;
  }

  return numero;
})()
}}

