const body = $input.first().json.body;
const type = body.type || '';
const name = body.clientName || '';
const service = body.serviceName || '';
const employee = body.employeeName || '';
const date = body.appointmentDate || '';
const time = body.appointmentTime || '';
const duration = body.serviceDuration || '';
const professional = body.professionalName || '';
const link = body.managementLink || '';
const oldDate = body.oldDate || '';
const oldTime = body.oldTime || '';
const reason = body.reason || '';
const price = body.servicePrice || '';
const number = $input.first().json.data[0].jid || '';

// Formatar data DD/MM/YYYY
const formatDate = (d) => {
  if (!d) return '';
  const parts = d.split('-');
  return parts.length === 3 ? `${parts[2]}/${parts[1]}/${parts[0]}` : d;
};

// Formatar preço
const formatPrice = (p) => {
  if (!p) return '';
  const num = parseInt(p) / 100;
  return num.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
};

let message = '';

switch (type) {
  case 'reminder_7d':
    message = `📅 *Lembrete de Agendamento*\n\n`
      + `Olá *${name}*!\n\n`
      + `Você tem um agendamento em *7 dias*:\n\n`
      + `📋 *Serviço:* ${service}\n`
      + `👤 *Profissional:* ${employee}\n`
      + `📅 *Data:* ${formatDate(date)}\n`
      + `🕐 *Horário:* ${time}\n`
      + `⏱️ *Duração:* ${duration} min\n`
      + (price ? `💰 *Valor:* ${formatPrice(price)}\n` : '')
      + `\nPrecisa remarcar ou cancelar?\n`
      + `Acesse: ${link}\n\n`

      + `Não responda essa mensagem pois ela é automática.\n`
      + `Desenvolvido por HFerraz Automação.`;
    break;

  case 'reminder_24h':
    message = `⏰ *Lembrete de Agendamento*\n\n`
      + `Olá *${name}*!\n\n`
      + `Seu agendamento é *amanhã*!\n\n`
      + `📋 *Serviço:* ${service}\n`
      + `👤 *Profissional:* ${employee}\n`
      + `📅 *Data:* ${formatDate(date)}\n`
      + `🕐 *Horário:* ${time}\n`
      + `⏱️ *Duração:* ${duration} min\n`
      + (price ? `💰 *Valor:* ${formatPrice(price)}\n` : '')
      + `\nPrecisa remarcar ou cancelar?\n`
      + `Acesse: ${link}\n\n`

      + `Não responda essa mensagem pois ela é automática.\n`
      + `Desenvolvido por HFerraz Automação.`;
    break;

  case 'reminder_2h':
    message = `⚡ *Seu agendamento é em 2 horas!*\n\n`
      + `Olá *${name}*!\n\n`
      + `📋 *Serviço:* ${service}\n`
      + `👤 *Profissional:* ${employee}\n`
      + `📅 *Data:* ${formatDate(date)}\n`
      + `🕐 *Horário:* ${time}\n`
      + `⏱️ *Duração:* ${duration} min\n`
      + (price ? `💰 *Valor:* ${formatPrice(price)}\n` : '')
      + `\n⚡ *Faltam apenas 2 horas!*\n\n`
      + `Precisa remarcar ou cancelar?\n`
      + `Acesse: ${link}\n\n`

      + `Não responda essa mensagem pois ela é automática.\n`
      + `Desenvolvido por HFerraz Automação.`;
    break;

  case 'professional_new_appointment':
    message = `📌 *Novo Agendamento!*\n\n`
      + `👤 *Cliente:* ${name}\n`
      + `📋 *Serviço:* ${service}\n`
      + `👨‍💼 *Profissional:* ${employee}\n`
      + `📅 *Data:* ${formatDate(date)}\n`
      + `🕐 *Horário:* ${time}\n`
      + `⏱️ *Duração:* ${duration} min\n`
      + (price ? `💰 *Valor:* ${formatPrice(price)}\n` : '');
    break;

  case 'professional_cancel':
    message = `❌ *Agendamento Cancelado*\n\n`
      + `👤 *Cliente:* ${name}\n`
      + `📋 *Serviço:* ${service}\n`
      + `📅 *Data:* ${formatDate(date)}\n`
      + `🕐 *Horário:* ${time}\n`
      + (reason ? `📝 *Motivo:* ${reason}\n` : '');
    break;

  case 'professional_reschedule':
    message = `🔄 *Agendamento Remarcado*\n\n`
      + `👤 *Cliente:* ${name}\n`
      + `📋 *Serviço:* ${service}\n`
      + `📅 *De:* ${formatDate(oldDate)} ${oldTime}\n`
      + `📅 *Para:* ${formatDate(date)} ${time}\n`
      + (reason ? `📝 *Motivo:* ${reason}\n` : '');
    break;

      case 'custom_individual':
    message = body.message || `Mensagem do profissional para ${name}.`;
    break;

  case 'custom_bulk':
    message = body.message || `Mensagem do profissional para ${name}.`;
    break;

  case 'unavailability':
    message = `⚠️ *Aviso de Indisponibilidade*\n\n`
      + `Olá *${name}*!\n\n`
      + (reason ? `📝 *Motivo:* ${reason}\n\n` : '')
      + `Seu agendamento foi afetado:\n`
      + `📋 *Serviço:* ${service}\n`
      + `👤 *Profissional:* ${employee}\n`
      + `📅 *Data:* ${formatDate(date)}\n`
      + `🕐 *Horário:* ${time}\n\n`
      + (link ? `Precisa reagendar?\nAcesse: ${link}\n\n` : '')
      + `Não responda essa mensagem pois ela é automática.\n`
      + `Desenvolvido por HFerraz Automação.`;
    break;

  default:
    // Fallback: usa o campo message direto
    message = body.message || `Mensagem do tipo "${type}" recebida.`;
}

return [{ json: { ...body, number, formattedMessage: message } }];
